import { z } from 'zod'

const name = z.string().refine((value) => value.trim() !== '', 'must not be blank')
const missingToken = 'Set GOOGLE_MEET_ACCESS_TOKEN or pass accessToken.'
const accessToken = z.string().optional().pipe(z.string({ error: missingToken }).trim().min(1, missingToken))

export const googleMeetConfigSchema = z.object({
  /** Stable, non-secret label for one authenticated Google account. */
  sourceId: name,
  /** Journal identities use this prefix; change it for a separate installation. */
  streamPrefix: name,
  database: name,
  /** Re-read recent completed calls and their children; defaults to 24 hours. */
  lookbackHours: z.number().positive(),
  /** Small discovery pages bound how many conferences replay after interruption. */
  pageSize: z.int().min(1).max(100),
  maxChunks: z.int().positive(),
  /** OAuth access token; read when a stream runs, never by schema commands. */
  accessToken,
})

export type GoogleMeetConfig = z.input<typeof googleMeetConfigSchema>

/** Runtime settings; the exported destination schemas use database at setup time. */
export const googleMeetReaderConfigSchema = googleMeetConfigSchema.omit({ database: true })
export type GoogleMeetReaderConfig = z.input<typeof googleMeetReaderConfigSchema>

// Set schema placement before importing index.ts.
export const googleMeetConfig: GoogleMeetConfig = {
  sourceId: 'google-meet.primary',
  streamPrefix: 'google-meet',
  database: 'default',
  lookbackHours: 24,
  pageSize: 1,
  maxChunks: 200,
  accessToken: process.env.GOOGLE_MEET_ACCESS_TOKEN,
}

import { HttpError, paginate, type Page, type SourceContext } from '@chkit/plugin-ingest'
import { z } from 'zod'

import { googleMeetReaderConfigSchema, type GoogleMeetReaderConfig } from './config.js'

export interface Named { name: string; [key: string]: unknown }
export interface CollectionCursor { pageToken?: string; recoveryCount?: number }
export interface CollectionOptions { filter?: string; initial?: CollectionCursor; pageSize?: number }
export type GoogleMeetSettings = Omit<z.output<typeof googleMeetReaderConfigSchema>, 'accessToken'>

export interface GoogleMeetClient {
  settings: GoogleMeetSettings
  collection(path: string, field: string, options?: CollectionOptions): AsyncGenerator<Page<Named, CollectionCursor, { reset: true }>>
}

const pageEnvelope = z.looseObject({ nextPageToken: z.string().min(1).optional() })
const resource = z.looseObject({ name: z.string().min(1) })

export function createGoogleMeetClient(context: SourceContext, config: GoogleMeetReaderConfig): GoogleMeetClient {
  const { accessToken, ...settings } = googleMeetReaderConfigSchema.parse(config)
  const get = (url: URL) => context.fetch(url, { headers: { Authorization: `Bearer ${accessToken}` }, redirect: 'error' })
  return {
    settings,
    collection: (path, field, options = {}) => paginate<Named, CollectionCursor, { reset: true }>({
      context, initial: options.initial ?? {}, label: `GET ${field}`,
      fetchPage: async (cursor) => {
        const current = cursor ?? {}
        const page = await requestPage(get, path, field, current.pageToken, options)
        if ('reset' in page) {
          if (current.recoveryCount) throw new Error(`Meet ${field} repeatedly rejected its page token. Increase the execution budget or migrate the checkpoint after reviewing coverage.`)
          return { items: [], next: { recoveryCount: 1 }, metadata: { reset: true } }
        }
        return { items: page.items, next: page.nextPageToken ? { ...current, pageToken: page.nextPageToken } : undefined }
      },
    }),
  }
}

async function requestPage(get: (url: URL) => Promise<Response>, path: string, field: string, pageToken: string | undefined, options: CollectionOptions): Promise<{ items: Named[]; nextPageToken?: string } | { reset: true }> {
  const pageSize = options.pageSize ?? 100
  const url = new URL(`https://meet.googleapis.com/v2/${path}`)
  url.searchParams.set('pageSize', String(pageSize))
  if (options.filter) url.searchParams.set('filter', options.filter)
  if (pageToken) url.searchParams.set('pageToken', pageToken)
  let response: Response
  try {
    response = await get(url)
  } catch (error) {
    if (pageToken && isRejectedPageToken(error)) return { reset: true }
    throw error
  }
  const payload = pageEnvelope.parse(await response.json())
  const items = z.array(resource).max(pageSize).optional().parse(payload[field]) ?? []
  for (const item of items) {
    const child = item.name.slice(path.length + 1)
    const inside = field === 'conferenceRecords'
      ? /^conferenceRecords\/[^/?#]+$/.test(item.name)
      : item.name.startsWith(`${path}/`) && !child.includes('/') && !/[?#]/.test(child)
    if (!inside) throw new Error(`Meet ${field} returned a resource outside its requested parent.`)
  }
  return { items, nextPageToken: payload.nextPageToken }
}

function isRejectedPageToken(error: unknown): boolean {
  return error instanceof HttpError && (error.status === 400 || error.status === 410)
    && /page[_\s-]*token/i.test(error.body) && /invalid|expir/i.test(error.body)
}

import { cursorState, definePipeline, defineStream } from '@chkit/plugin-ingest'

import { googleMeetConfig, type GoogleMeetReaderConfig } from './config.js'
import { google_meet_conferencesRaw, google_meet_transcriptsRaw, google_meet_transcriptEntriesRaw, google_meet_participantsRaw, google_meet_participantSessionsRaw, google_meet_recordingsRaw, parseMeetState, readResource, type MeetSelection, type MeetState, type Resource } from './sources/resources.js'

export function createGoogleMeetPipeline(config: GoogleMeetReaderConfig = googleMeetConfig) {
  const boundConfig = { ...config }
  return definePipeline({
    id: boundConfig.streamPrefix, tags: ['provider:google-meet'], maxStreams: 1, maxFetches: 1,
    streams: [
      resourceStream('conferences', google_meet_conferencesRaw, boundConfig),
      resourceStream('transcripts', google_meet_transcriptsRaw, boundConfig),
      resourceStream('transcript-entries', google_meet_transcriptEntriesRaw, boundConfig),
      resourceStream('participants', google_meet_participantsRaw, boundConfig),
      resourceStream('participant-sessions', google_meet_participantSessionsRaw, boundConfig),
      resourceStream('recordings', google_meet_recordingsRaw, boundConfig),
    ],
  })
}

export const google_meetPipeline = createGoogleMeetPipeline()

function resourceStream(resource: Resource, destination: typeof google_meet_conferencesRaw, config: GoogleMeetReaderConfig) {
  const checkpoint = cursorState({ id: `${config.streamPrefix}.${resource}.pages`, version: 2, parse: (raw) => parseMeetState(raw, config) })
  return defineStream<Record<string, unknown>, MeetState, MeetSelection>({
    id: `${config.streamPrefix}.${resource}`, tags: [`resource:${resource}`], destination,
    incremental: {
      id: checkpoint.id, version: checkpoint.version, parseState: checkpoint.parseState,
      plan: ({ range }) => {
        for (const bound of [range?.from, range?.to]) {
          if (bound !== undefined && (!(bound instanceof Date) || !Number.isFinite(bound.getTime()))) throw new Error('Meet backfill bounds must be valid dates.')
        }
        return range
      },
    },
    batchSize: 1,
    budget: { maxChunks: config.maxChunks, maxChunkRows: 100 },
    read: (context) => readResource(context, resource, config),
  })
}

import { rawRows, rawTable, type ReadContext, type SourceChunk } from '@chkit/plugin-ingest'
import { z } from 'zod'

import { createGoogleMeetClient, type CollectionCursor, type GoogleMeetClient, type Named } from '../client.js'
import { googleMeetConfig, type GoogleMeetReaderConfig } from '../config.js'

const hourMs = 3_600_000
const timestamp = z.string().refine((value) => Number.isFinite(Date.parse(value)), 'must be a timestamp')
const stateSchema = z.strictObject({
  scope: z.string(),
  watermark: timestamp.optional(),
  bounds: z.strictObject({ from: timestamp.optional(), to: timestamp.optional() }).optional(),
  window: z.strictObject({
    from: timestamp,
    to: timestamp,
    phase: z.enum(['ended', 'ongoing']),
    pageToken: z.string().refine((value) => value.trim() !== '', 'must not be blank').optional(),
    recoveryCount: z.literal(1).optional(),
  }).optional(),
})

export type Resource = 'conferences' | 'transcripts' | 'transcript-entries' | 'participants' | 'participant-sessions' | 'recordings'
interface Bounds { from?: string; to?: string }
interface Window extends CollectionCursor { from: string; to: string; phase: 'ended' | 'ongoing' }
export interface MeetState { scope: string; watermark?: string; bounds?: Bounds; window?: Window }
export type MeetSelection = { from: Date | undefined; to: Date | undefined } | undefined
type MeetContext = ReadContext<MeetSelection, MeetState>
type MeetChunk = SourceChunk<Record<string, unknown>, MeetState>

export const google_meet_conferencesRaw = rawTable({ database: googleMeetConfig.database, name: 'google_meet_conferences_raw' })
export const google_meet_transcriptsRaw = rawTable({ database: googleMeetConfig.database, name: 'google_meet_transcripts_raw' })
export const google_meet_transcriptEntriesRaw = rawTable({ database: googleMeetConfig.database, name: 'google_meet_transcript_entries_raw' })
export const google_meet_participantsRaw = rawTable({ database: googleMeetConfig.database, name: 'google_meet_participants_raw' })
export const google_meet_participantSessionsRaw = rawTable({ database: googleMeetConfig.database, name: 'google_meet_participant_sessions_raw' })
export const google_meet_recordingsRaw = rawTable({ database: googleMeetConfig.database, name: 'google_meet_recordings_raw' })

// Every resource independently discovers conferences and replays unfinished parent pages.
export async function* readResource(context: MeetContext, resource: Resource, config: GoogleMeetReaderConfig): AsyncGenerator<MeetChunk> {
  const client = createGoogleMeetClient(context, config)
  const scope = meetScope(client.settings)
  let state: MeetState = context.state ?? { scope }
  const requestedBounds = context.selection?.from || context.selection?.to
    ? { from: context.selection.from?.toISOString(), to: context.selection.to?.toISOString() }
    : undefined
  if (requestedBounds && state.bounds && JSON.stringify(requestedBounds) !== JSON.stringify(state.bounds)) throw new Error('Meet backfill bounds changed. Use a new backfill ID.')
  if (requestedBounds && state.watermark && !state.bounds) throw new Error('Meet checkpoint was created without date bounds. Use a new backfill ID.')
  state = { ...state, bounds: state.bounds ?? requestedBounds }
  if (!state.window) {
    const to = state.bounds?.to ?? context.cutoff.toISOString()
    const anchor = state.watermark ?? to
    const lowerBound = state.bounds?.from ? new Date(state.bounds.from) : new Date(Date.parse(anchor) - client.settings.lookbackHours * hourMs)
    if (!Number.isFinite(lowerBound.getTime())) throw new Error('Meet lookbackHours places the lower bound outside the Date range.')
    const from = state.bounds?.from ?? lowerBound.toISOString()
    if (Date.parse(from) > Date.parse(to) || state.watermark && Date.parse(state.watermark) > Date.parse(to)) throw new Error('Meet cutoff precedes its committed range.')
    state = { ...state, window: { from, to, phase: 'ended' } }
    yield progress(state)
  }
  while (state.window) {
    const window = state.window
    const filter = window.phase === 'ended'
      ? `end_time>="${window.from}" AND end_time<="${window.to}"`
      : `end_time IS NULL AND start_time<="${window.to}"`
    for await (const page of client.collection('conferenceRecords', 'conferenceRecords', { filter, initial: { pageToken: window.pageToken, recoveryCount: window.recoveryCount }, pageSize: client.settings.pageSize })) {
      if (!page.metadata?.reset) {
        for (const conference of page.items) {
          if (resource === 'conferences') yield { rows: rawRows([conference], (item) => JSON.stringify([client.settings.sourceId, item.name])) }
          else yield* readChildren(client, resource, conference)
        }
      }
      state = page.next
        ? { ...state, window: { from: window.from, to: window.to, phase: window.phase, ...page.next } }
        : window.phase === 'ended' && !state.bounds
          ? { ...state, window: { from: window.from, to: window.to, phase: 'ongoing' } }
          : { scope, bounds: state.bounds, watermark: window.to }
      // Flush all child rows before advancing discovery. Partial pages replay on resume.
      yield progress(state)
    }
  }
}

export function parseMeetState(raw: unknown, config: GoogleMeetReaderConfig): MeetState {
  const scope = meetScope(config)
  const parsed = stateSchema.safeParse(raw)
  if (!parsed.success || parsed.data.scope !== scope) {
    throw new Error('Meet checkpoint scope or format changed. Migrate the state explicitly or use a new stream ID.', { cause: parsed.error })
  }
  const { bounds, window, watermark } = parsed.data
  if (bounds && (!bounds.from && !bounds.to || bounds.from && bounds.to && Date.parse(bounds.from) > Date.parse(bounds.to))) throw new Error('Meet backfill bounds are invalid.')
  if (window) {
    if (bounds && window.phase === 'ongoing') throw new Error('Meet discovery window is invalid.')
    if (Date.parse(window.from) > Date.parse(window.to) || bounds?.from && window.from !== bounds.from || bounds?.to && window.to !== bounds.to) throw new Error('Meet discovery bounds are invalid.')
  }
  if (!window && !watermark) throw new Error('Meet checkpoint has no discovery progress.')
  return { scope, watermark, bounds, window }
}

async function* readChildren(client: GoogleMeetClient, resource: Exclude<Resource, 'conferences'>, conference: Named): AsyncGenerator<MeetChunk> {
  const collection = resource === 'transcript-entries' ? 'transcripts' : resource === 'participant-sessions' ? 'participants' : resource
  for await (const page of client.collection(`${conference.name}/${collection}`, collection)) {
    if (resource === 'transcript-entries' || resource === 'participant-sessions') {
      const child = resource === 'transcript-entries' ? 'entries' : 'participantSessions'
      const field = resource === 'transcript-entries' ? 'transcriptEntries' : child
      const parentField = resource === 'transcript-entries' ? 'transcript_name' : 'participant_name'
      for (const parent of page.items) {
        for await (const children of client.collection(`${parent.name}/${child}`, field)) {
          yield { rows: rawRows(children.items.map((item) => ({ ...item, conference_name: conference.name, [parentField]: parent.name })), (item) => JSON.stringify([client.settings.sourceId, item.name])) }
        }
      }
      if (!page.items.length) yield { rows: [] }
    } else {
      yield { rows: rawRows(page.items.map((item) => ({ ...item, conference_name: conference.name })), (item) => JSON.stringify([client.settings.sourceId, item.name])) }
    }
  }
}

function progress(state: MeetState): MeetChunk {
  return { rows: [], state, id: 'meet-discovery-progress' }
}

function meetScope(config: Pick<GoogleMeetReaderConfig, 'sourceId' | 'lookbackHours' | 'pageSize'>): string {
  return JSON.stringify([config.sourceId, config.lookbackHours, config.pageSize])
}

import { expect, test } from 'bun:test'
import { runIngestion, selectStreams } from '@chkit/plugin-ingest'
import { createMemoryDestination, createMemoryJournal } from '@chkit/plugin-ingest/testing'

import { googleMeetConfig, type GoogleMeetReaderConfig } from '../config.js'
import { createGoogleMeetPipeline } from '../pipeline.js'
import { parseMeetState, type Resource } from '../sources/resources.js'

const cutoff = new Date('2026-10-05T00:00:00Z')
const fixtureConfig = { ...googleMeetConfig, accessToken: 'fixture' }
const conference = { name: 'conferenceRecords/c1', startTime: '2026-10-02T00:00:00Z', endTime: '2026-10-04T12:00:00Z', expireTime: '2026-11-03T12:00:00Z' }
const transcript = { name: `${conference.name}/transcripts/t1`, state: 'FILE_GENERATED' }
const entry = { name: `${transcript.name}/entries/e1`, text: 'first' }
const participant = { name: `${conference.name}/participants/p1`, signedinUser: { user: 'users/u1' } }
const session = { name: `${participant.name}/participantSessions/s1`, startTime: conference.startTime }
const recording = { name: `${conference.name}/recordings/r1`, state: 'FILE_GENERATED', driveDestination: { file: 'drive-file-1' } }
const resources: readonly Resource[] = ['conferences', 'transcripts', 'transcript-entries', 'participants', 'participant-sessions', 'recordings']

test('Meet replays an unfinished discovery page and its entries under the original window', async () => {
  const urls: URL[] = []
  const env = meetEnv((url) => { urls.push(url); return fixture(url) })
  const pipeline = fixturePipeline()
  const initial = createMemoryJournal()
  const destination = createMemoryDestination()
  const first = await runIngestion(request(pipeline, 'transcript-entries', 2), { ...env, journal: initial, destination, now: () => cutoff })
  expect(first.streams[0]?.outcome).toBe('budget_exhausted')
  const checkpoint = await initial.readCheckpoint('google-meet.transcript-entries')
  expect(checkpoint.envelope?.state).toMatchObject({ window: { from: '2026-10-04T00:00:00.000Z', to: cutoff.toISOString(), phase: 'ended' } })
  expect(checkpoint.envelope?.state).not.toHaveProperty('watermark')
  expect(checkpoint.envelope?.state).not.toHaveProperty('active')
  const previous = urls.length
  const journal = restoredJournal(initial)
  const resumed = await runIngestion(request(pipeline), { ...env, journal, destination, now: () => new Date('2026-10-06T00:00:00Z') })
  expect(resumed.ok, JSON.stringify(resumed)).toBe(true)
  expect(urls[previous]?.pathname).toBe('/v2/conferenceRecords')
  expect(urls[previous]?.searchParams.get('filter')).toBe(urls[0]?.searchParams.get('filter'))
  expect(urls[previous + 1]?.pathname).toBe(`/v2/${conference.name}/transcripts`)
  expect(urls[previous + 2]?.searchParams.has('pageToken')).toBe(false)
  expect(new Set(destination.tables.get('default.google_meet_transcript_entries_raw')?.map((row) => row.id)).size).toBe(2)
  expect((await journal.readCheckpoint('google-meet.transcript-entries')).envelope?.state).toMatchObject({ watermark: cutoff.toISOString() })
})

test('Meet completes every parent on a discovery page before saving its continuation', async () => {
  const other = { ...conference, name: 'conferenceRecords/c2' }
  const urls: URL[] = []
  const env = meetEnv((url) => {
    urls.push(url)
    if (url.pathname === '/v2/conferenceRecords') return Response.json({ conferenceRecords: url.searchParams.get('filter')?.includes('IS NULL') ? [] : [conference, other] })
    return fixture(url)
  })
  const pipeline = fixturePipeline({ ...fixtureConfig, pageSize: 2 })
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  expect((await runIngestion(request(pipeline, 'transcript-entries', 3), { ...env, journal, destination, now: () => cutoff })).streams[0]?.outcome).toBe('budget_exhausted')
  expect((await journal.readCheckpoint('google-meet.transcript-entries')).envelope?.state).toHaveProperty('window')
  const previous = urls.length
  expect((await runIngestion(request(pipeline), { ...env, journal, destination, now: () => cutoff })).ok).toBe(true)
  expect(urls.slice(previous).some((url) => url.pathname === `/v2/${other.name}/transcripts`)).toBe(true)
  expect(new Set(destination.tables.get('default.google_meet_transcript_entries_raw')?.map((row) => row.id)).size).toBe(4)
})

test('Meet resumes at the next discovery page after completing an earlier parent', async () => {
  const other = { ...conference, name: 'conferenceRecords/c2' }
  const urls: URL[] = []
  const env = meetEnv((url) => {
    urls.push(url)
    if (url.pathname === '/v2/conferenceRecords') return Response.json(url.searchParams.get('filter')?.includes('IS NULL') ? { conferenceRecords: [] } : url.searchParams.has('pageToken')
      ? { conferenceRecords: [other] } : { conferenceRecords: [conference], nextPageToken: 'parents-next' })
    return fixture(url)
  })
  const pipeline = fixturePipeline()
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  expect((await runIngestion(request(pipeline, 'transcript-entries', 4), { ...env, journal, destination, now: () => cutoff })).streams[0]?.outcome).toBe('budget_exhausted')
  expect((await journal.readCheckpoint('google-meet.transcript-entries')).envelope?.state).toMatchObject({ window: { pageToken: 'parents-next' } })
  const previous = urls.length
  expect((await runIngestion(request(pipeline), { ...env, journal, destination, now: () => cutoff })).ok).toBe(true)
  expect(urls[previous]?.searchParams.get('pageToken')).toBe('parents-next')
  expect(urls.slice(previous).some((url) => url.pathname.startsWith(`/v2/${conference.name}/`))).toBe(false)
  expect(new Set(destination.tables.get('default.google_meet_transcript_entries_raw')?.map((row) => row.id)).size).toBe(4)
})

test('Meet replays child rows after lost destination acknowledgement without advancing discovery', async () => {
  const env = meetEnv()
  const pipeline = fixturePipeline()
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  const failed = await runIngestion(request(pipeline), { ...env, journal, destination: {
    async insert(input) {
      await destination.insert(input)
      if (input.rows.some((row) => JSON.stringify(row.raw).includes('second'))) throw new Error('lost acknowledgement')
    },
  }, now: () => cutoff })
  expect(failed.ok).toBe(false)
  expect((await journal.readCheckpoint('google-meet.transcript-entries')).envelope?.state).toHaveProperty('window')
  expect((await journal.readCheckpoint('google-meet.transcript-entries')).envelope?.state).not.toHaveProperty('watermark')
  expect((await runIngestion(request(pipeline), { ...env, journal, destination, now: () => cutoff })).ok).toBe(true)
  expect(new Set(destination.tables.get('default.google_meet_transcript_entries_raw')?.map((row) => row.id)).size).toBe(2)
})

test('Meet replay publishes changed child content under the same raw identity', async () => {
  let changed = false
  const env = meetEnv((url) => url.pathname.endsWith('/entries') && !url.searchParams.has('pageToken')
    ? Response.json({ transcriptEntries: [{ ...entry, text: changed ? 'revised' : 'first' }], nextPageToken: 'entries-next' })
    : fixture(url))
  const pipeline = fixturePipeline()
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  expect((await runIngestion(request(pipeline, 'transcript-entries', 2), { ...env, journal, destination, now: () => cutoff })).streams[0]?.outcome).toBe('budget_exhausted')
  changed = true
  expect((await runIngestion(request(pipeline), { ...env, journal, destination, now: () => cutoff })).ok).toBe(true)
  const versions = destination.tables.get('default.google_meet_transcript_entries_raw')?.filter((row) => row.id === JSON.stringify([googleMeetConfig.sourceId, entry.name]))
  expect(versions?.map((row) => row.raw)).toEqual([
    { ...entry, conference_name: conference.name, transcript_name: transcript.name },
    { ...entry, text: 'revised', conference_name: conference.name, transcript_name: transcript.name },
  ])
})

test('Meet discovers the preceding 24 hours by end time and also includes ongoing calls', async () => {
  const urls: URL[] = []
  const ongoing = { ...conference, name: 'conferenceRecords/ongoing', endTime: undefined }
  const env = meetEnv((url) => {
    urls.push(url)
    return Response.json({ conferenceRecords: url.searchParams.get('filter')?.includes('IS NULL') ? [ongoing] : [conference] })
  })
  const pipeline = fixturePipeline()
  const destination = createMemoryDestination()
  expect((await runIngestion(request(pipeline, 'conferences'), { ...env, journal: createMemoryJournal(), destination, now: () => cutoff })).ok).toBe(true)
  expect(urls.map((url) => url.searchParams.get('filter'))).toEqual([
    'end_time>="2026-10-04T00:00:00.000Z" AND end_time<="2026-10-05T00:00:00.000Z"',
    'end_time IS NULL AND start_time<="2026-10-05T00:00:00.000Z"',
  ])
  expect(urls.map((url) => url.searchParams.get('pageSize'))).toEqual(['1', '1'])
  expect(destination.tables.get('default.google_meet_conferences_raw')).toHaveLength(2)
})

test('Meet catches up from its completed watermark while rereading a 24-hour overlap', async () => {
  const filters: Array<string | null> = []
  const env = meetEnv((url) => { filters.push(url.searchParams.get('filter')); return Response.json({ conferenceRecords: [] }) })
  const pipeline = fixturePipeline()
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  expect((await runIngestion(request(pipeline, 'conferences'), { ...env, journal, destination, now: () => cutoff })).ok).toBe(true)
  expect((await runIngestion(request(pipeline, 'conferences'), { ...env, journal, destination, now: () => new Date('2026-10-07T00:00:00Z') })).ok).toBe(true)
  expect(filters[2]).toBe('end_time>="2026-10-04T00:00:00.000Z" AND end_time<="2026-10-07T00:00:00.000Z"')
})

test('Meet discovers a late transcript within the lookback without a not-ready placeholder', async () => {
  let ready = false
  const env = meetEnv((url) => url.pathname.endsWith('/transcripts') && !ready ? Response.json({ transcripts: [] }) : fixture(url))
  const pipeline = fixturePipeline()
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  expect((await runIngestion(request(pipeline), { ...env, journal, destination, now: () => cutoff })).ok).toBe(true)
  expect(destination.tables.size).toBe(0)
  ready = true
  expect((await runIngestion(request(pipeline), { ...env, journal, destination, now: () => new Date('2026-10-05T06:00:00Z') })).ok).toBe(true)
  expect(new Set(destination.tables.get('default.google_meet_transcript_entries_raw')?.map((row) => row.id)).size).toBe(2)
})

test('Meet does not retain old conference IDs after they leave discovery', async () => {
  let visible = true
  let children = 0
  const env = meetEnv((url) => {
    if (url.pathname === '/v2/conferenceRecords' && !visible) return Response.json({ conferenceRecords: [] })
    if (url.pathname.endsWith('/transcripts')) children += 1
    return fixture(url)
  })
  const pipeline = fixturePipeline()
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  expect((await runIngestion(request(pipeline, 'transcripts'), { ...env, journal, destination, now: () => cutoff })).ok).toBe(true)
  const previous = children
  visible = false
  expect((await runIngestion(request(pipeline, 'transcripts'), { ...env, journal, destination, now: () => new Date('2026-10-06T06:00:00Z') })).ok).toBe(true)
  expect(children).toBe(previous)
